    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def blocks(size, separators):
        result = []
        start = 0
        for pos in separators:
            if start < pos:
                result.append((start, pos))
            start = pos + 1
        if start < size:
            result.append((start, size))
        return result

    rows = blocks(h, sep_rows)
    cols = blocks(w, sep_cols)

    output = []
    for r0, r1 in rows:
        out_row = []
        for c0, c1 in cols:
            markers = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if markers == 2 else background)
        output.append(out_row)
    return output
